// src/service/main/dialect/alter/alterDialect.ts
var Id = class {
  constructor(e) {
    this.param = e;
    this.afterTablePrefix = `ALTER TABLE "${e.table}"`, this.afterColumnPrefix = `${this.afterTablePrefix} ALTER COLUMN "${e.columnName}"`;
  }
  genAlterSQL() {
    let { columnName: e, newColumnName: t } = this.param;
    return new pt("", `
`).append(this.changeTypePart()).append(this.notNullPart()).append(this.defaultPart()).append(this.otherPart()).append(this.commentPart()).if(e != t, `${this.afterTablePrefix} RENAME COLUMN "${e}" TO "${t}";`).toString();
  }
  changeTypePart() {
    let { oldRow: e, columnType: t } = this.param;
    return e.type == t ? "" : `${this.afterColumnPrefix} TYPE ${t};`;
  }
  notNullPart() {
    let { oldRow: e, isNotNull: t } = this.param;
    return e.isNotNull == t ? "" : `${this.afterColumnPrefix} ${t ? "SET NOT NULL" : "DROP NOT NULL"};`;
  }
  otherPart() {
    return null;
  }
  defaultPart() {
    let { oldRow: e, defaultValue: t, columnType: n } = this.param;
    return e.defaultValue == t ? "" : `${this.afterColumnPrefix} ${Au(t) ? "DROP DEFAULT" : `SET DEFAULT ${gl(t, n)}`};`;
  }
  /**
   * 注释没有SQL标准, 每种数据库都有各自的方言
   */
  commentPart() {
    return "";
  }
};

