    return o && o != s && (u = `ALTER TABLE \`${t}\` COMMENT = '${o}';`), c && c != a && (u += `ALTER TABLE \`${t}\` collate = '${c}';`), n && t != n && (u += `ALTER TABLE \`${t}\` RENAME TO \`${n}\`;`), u;
