// src/service/main/dialect/kingbaseSQLDialect.ts
var f2 = class extends Cd {
  showVersion() {
    return "select replace(version(), 'KingbaseES ', '');";
  }
  showViewSource(e, t, n) {
    return n ? `SELECT 
    'CREATE MATERIALIZED VIEW ' || schemaname || '.' || matviewname || ' AS ' ||
    definition as mview_ddl
FROM sys_matviews
WHERE schemaname = '${e}' 
    AND matviewname = '${t}';` : `SELECT 
    'CREATE OR REPLACE VIEW ' || schemaname || '.' || viewname || ' AS ' || 
    definition as view_ddl
FROM sys_views 
WHERE schemaname = '${e}' 
    AND viewname = '${t}';`;
  }
  triggerTemplate(e) {
    return `CREATE TRIGGER trigger_name$1
[BEFORE/AFTER] INSERT ON ${e ?? "[table_name]$2"}
FOR EACH ROW BEGIN
    $3
END;`;
  }
};

