function ODt(r, e) {
  let t = 0;
  for (let n = e; n < r.length; n++) {
    let s = r[n];
    if (s.text === "<" ? t++ : s.text === ">" ? t-- : s.text === ">>" && (t -= 2), t === 0)
      return n;
  }
  return r.length - 1;
}

