// src/bin/sql-formatter/languages/mariadb/likeMariaDb.ts
function QS(r) {
  return r.map((e, t) => {
    let n = r[t + 1] || Md;
    if (bf.SET(e) && n.text === "(")
      return { ...e, type: "RESERVED_FUNCTION_NAME" };
    let s = r[t - 1] || Md;
    return bf.VALUES(e) && s.text === "=" ? { ...e, type: "RESERVED_FUNCTION_NAME" } : e;
  });
}

